-- Additive: no changes to lessons, entitlement policies, progress or XP rules.
alter table public.soma_learning_lessons add column if not exists minigames jsonb not null default '[]'::jsonb;
alter table public.soma_learning_lessons add constraint soma_learning_minigames_array check (jsonb_typeof(minigames)='array' and jsonb_array_length(minigames)<=6);
-- Existing column-level SELECT grants deliberately exclude answer-bearing minigames.
revoke select(minigames) on public.soma_learning_lessons from public,anon,authenticated;
grant select(minigames),update(minigames) on public.soma_learning_lessons to service_role;

update public.soma_learning_lessons set minigames='[{"id": "mapa-conceitos", "kind": "matching", "title": "Reconheça seu ponto de partida", "prompt": "Relacione cada parte do diagnóstico ao que ela ajuda a observar.", "items": ["Valores", "Habilidades", "Pontos de desenvolvimento"], "matches": ["O que orienta minhas decisões", "O que consigo demonstrar em uma ação", "O que quero desenvolver com a prática"], "answer": 0, "explanation": "Valores orientam decisões; habilidades aparecem em ações; pontos de desenvolvimento indicam o que praticar. Use situações reais para sustentar sua reflexão."}, {"id": "mapa-sequencia", "kind": "sequence", "title": "Do diagnóstico à ação", "prompt": "Organize uma forma de transformar sua reflexão em um próximo passo.", "items": ["Escolher uma situação real", "Identificar a habilidade demonstrada", "Definir um ponto de desenvolvimento", "Planejar uma ação e uma data de revisão"], "matches": [], "answer": 0, "explanation": "O diagnóstico começa em uma experiência concreta. A partir dela, você reconhece habilidades e escolhe uma ação observável para desenvolver."}, {"id": "mapa-decisao", "kind": "decision", "title": "Busque evidências", "prompt": "Você escreveu “sou uma pessoa colaborativa”. Qual próximo passo ajuda a sustentar essa percepção?", "items": ["Acrescentar outros adjetivos positivos", "Descrever uma situação em que sua colaboração fez diferença", "Copiar a descrição de outro perfil"], "matches": [], "answer": 1, "explanation": "Uma situação real mostra como a habilidade apareceu. Descreva sua participação e o que observou, sem precisar expor detalhes pessoais."}]'::jsonb where title='Mapa quem sou: aula e diagnóstico' and minigames='[]'::jsonb;

update public.soma_learning_lessons set minigames='[{"id": "pdi-conceitos", "kind": "matching", "title": "Conecte seu PDI", "prompt": "Relacione cada parte do plano à pergunta que ela responde.", "items": ["Objetivo", "Ação", "Evidência", "Revisão"], "matches": ["O que quero desenvolver", "O que farei na prática", "Como observarei o avanço", "Quando vou avaliar e ajustar"], "answer": 0, "explanation": "Um PDI liga uma necessidade a uma ação viável, uma evidência observável e uma data para revisão."}, {"id": "pdi-sequencia", "kind": "sequence", "title": "Monte seu PDI", "prompt": "Organize os passos de um plano de desenvolvimento.", "items": ["Escolher uma necessidade de desenvolvimento", "Definir uma ação viável", "Escolher uma evidência de avanço", "Marcar uma data para revisar o plano"], "matches": [], "answer": 0, "explanation": "Comece pelo que deseja desenvolver. Escolha uma ação e uma evidência coerentes com esse objetivo, e combine quando rever o plano."}, {"id": "pdi-decisao", "kind": "decision", "title": "Escolha uma ação observável", "prompt": "Seu objetivo é apresentar projetos com mais clareza. Qual ação permite praticar e avaliar seu avanço?", "items": ["Assistir a vídeos sem aplicar o conteúdo", "Esperar até se sentir completamente pronta", "Apresentar um projeto, pedir feedback e revisar a mensagem"], "matches": [], "answer": 2, "explanation": "Apresentar, receber feedback e revisar cria uma oportunidade de prática com evidência de avanço. O conteúdo pode apoiar essa experiência."}]'::jsonb where title='Carreira e desenvolvimento: encontro completo' and minigames='[]'::jsonb;

update public.soma_learning_lessons set minigames='[{"id": "ikigai-conceitos", "kind": "matching", "title": "Explore suas possibilidades", "prompt": "Conecte os elementos da reflexão às perguntas.", "items": ["Interesses", "Habilidades", "Contribuição"], "matches": ["O que desperta minha curiosidade", "O que consigo realizar e demonstrar", "Que necessidade posso ajudar a atender"], "answer": 0, "explanation": "Interesses, habilidades e contribuição ajudam a construir hipóteses. A reflexão não precisa produzir uma única resposta definitiva para toda a carreira."}, {"id": "ikigai-sequencia", "kind": "sequence", "title": "Teste uma possibilidade", "prompt": "Organize um pequeno experimento de carreira.", "items": ["Escolher uma possibilidade", "Definir o que quero descobrir", "Realizar uma experiência com baixo compromisso", "Comparar a expectativa com o que observei"], "matches": [], "answer": 0, "explanation": "Um teste pequeno produz informação para ajustar sua direção. Defina a pergunta antes da experiência e registre o que descobriu."}, {"id": "ikigai-decisao", "kind": "decision", "title": "Transforme reflexão em experiência", "prompt": "Uma nova área despertou seu interesse, mas você ainda não conhece a rotina. O que ajuda a investigar?", "items": ["Conversar com alguém da área e experimentar uma atividade pequena", "Concluir que precisa mudar de carreira imediatamente", "Esperar ter certeza absoluta antes de pesquisar"], "matches": [], "answer": 0, "explanation": "Conversas e experiências pequenas ajudam a avaliar uma hipótese antes de assumir um compromisso maior."}]'::jsonb where title='Ikigai: aula completa' and minigames='[]'::jsonb;

update public.soma_learning_lessons set minigames='[{"id": "story-conceitos", "kind": "matching", "title": "Conecte sua narrativa", "prompt": "Relacione cada parte de uma história profissional ao seu papel.", "items": ["Contexto", "Contribuição", "Resultado"], "matches": ["A situação ou o desafio que existia", "O que você fez e como participou", "A mudança ou o aprendizado observado"], "answer": 0, "explanation": "Uma história clara explica a situação, sua participação e o que mudou. Preserve o contexto dos números e diferencie sua ação do resultado coletivo."}, {"id": "story-sequencia", "kind": "sequence", "title": "Organize sua história", "prompt": "Monte uma estrutura para apresentar uma experiência real.", "items": ["Apresentar o desafio e o contexto", "Explicar sua contribuição", "Mostrar um resultado ou aprendizado verificável"], "matches": [], "answer": 0, "explanation": "Contexto, contribuição e resultado ajudam o público a entender o valor da experiência. A estrutura orienta a conversa, sem exigir uma fala decorada."}, {"id": "story-decisao", "kind": "decision", "title": "Conte uma entrega com responsabilidade", "prompt": "Você participou de um resultado coletivo, mas não tem uma métrica confiável. Como contar essa experiência?", "items": ["Inventar um percentual aproximado", "Atribuir todo o resultado a você", "Explicar sua contribuição e uma mudança observável"], "matches": [], "answer": 2, "explanation": "Uma entrega qualitativa concreta é válida. Use somente números que consegue sustentar e deixe clara a participação das outras pessoas."}]'::jsonb where title='Storytelling: gravação do encontro' and minigames='[]'::jsonb;
